def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 2 and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            rs = [y for y, x in cells]
            cs = [x for y, x in cells]
            objects.append((min(rs), max(rs), min(cs), max(cs)))

    out = [row[:] for row in grid]
    for i, a in enumerate(objects):
        top1, bot1, left1, right1 = a
        for b in objects[i + 1:]:
            top2, bot2, left2, right2 = b

            # Connect horizontally aligned diamonds.
            center_r1 = (top1 + bot1) / 2
            center_r2 = (top2 + bot2) / 2
            if center_r1 == center_r2:
                if right1 < left2:
                    for c in range(right1 + 1, left2):
                        out[int(center_r1)][c] = 1
                elif right2 < left1:
                    for c in range(right2 + 1, left1):
                        out[int(center_r1)][c] = 1

            # Connect vertically aligned diamonds.
            center_c1 = (left1 + right1) / 2
            center_c2 = (left2 + right2) / 2
            if center_c1 == center_c2:
                if bot1 < top2:
                    for r in range(bot1 + 1, top2):
                        out[r][int(center_c1)] = 1
                elif bot2 < top1:
                    for r in range(bot2 + 1, top1):
                        out[r][int(center_c1)] = 1

    return out
